functions.template:
{%- set cpu = http('${metrics_url}/api/v1/query?query=cpu_usage_user%7Bcpu%3D%22cpu-total%22%2Chost%3D%22${host}%22%7D') -%}
{%- set ram = http('${metrics_url}/api/v1/query?query=mem_used_percent%7Bhost%3D%22${host}%22%7D') -%}
{%- set disk = http('${metrics_url}/api/v1/query?query=disk_used_percent%7Bhost%3D%22${host}%22%2Cpath%3D%22%2F%22%7D') -%}
{%- set up = http('${metrics_url}/api/v1/query?query=system_uptime%7Bhost%3D%22${host}%22%7D') -%}
{%- set cv = 0 -%}{%- if cpu.data.result | length -%}{%- set cv = cpu.data.result[0].value[1] | float -%}{%- endif -%}
{%- set rv = 0 -%}{%- if ram.data.result | length -%}{%- set rv = ram.data.result[0].value[1] | float -%}{%- endif -%}
{%- set dv = 0 -%}{%- if disk.data.result | length -%}{%- set dv = disk.data.result[0].value[1] | float -%}{%- endif -%}
{%- set uv = 0 -%}{%- if up.data.result | length -%}{%- set uv = up.data.result[0].value[1] | float -%}{%- endif -%}
[VictoriaMetrics] ${host}: CPU {{ cv | round(1) | replace('.', ',') }} %, RAM {{ rv | round(1) | replace('.', ',') }} %, Disk / {{ dv | round(0) }} %, Uptime {{ (uv / 86400) | round(1) | replace('.', ',') }} Tage
